                    setActiveIndex(currentIndex % rewardItems.length);
                    currentIndex++;

                    if (currentIndex > totalSteps) {
                        clearInterval(spin);
                        setIsSpinning(false);
                        setItemWinner(rewardItems[targetIndex])
                        handleCallbackUser()
                    }
                }, getSpinSpeed(currentIndex));
            }

        } catch (error: any) {
            console.log('====================================');
            console.log(error);
            console.log('====================================');
            message.error(error?.response?.data?.message || "Something went wrong");
            setIsSpinning(false);
        }
